export class ConsoleSink {
  report(message: string): void {
    console.error('logger log debug warning exception failed failure', message)
  }
}

export class BadgeEditor {
  validateBadge(name: string): boolean {
    if (name.length === 0) {
      this.errorMessage = 'required badge name'
      return false
    }
    this.errorMessage = ''
    return true
  }
}

